import React, { useEffect, useState } from 'react';

import styles from '../../css/Register.module.css'

import closIcon from '../../images/icon/cross-icon.png'
import { useDispatch, useSelector } from 'react-redux';
import { toggleModal } from '../../features/user/userSlice';

const Register = (props) => {
  const {user: {modal}} = useSelector((user) => user)
  const [toggle, setToggle] = useState(false)

  const dispatch = useDispatch()

  const toggleBack = () => {
    setToggle(!toggle)
  }

  useEffect(() => {
    dispatch(toggleModal(toggle))
  },[toggle])

  const handleModalContentClick = (event) => {
    event.stopPropagation(); // Предотвращаем всплытие события клика
  };

  const [values, setValues] = useState({
    name: "",
    email: "",
    password: "",
  })

  const handleChange = ({target: {value, name}}) => {
    setValues({...values, [name]: value})
  }

  return (
    <>
      <div onClick={toggleModal} className={modal ? 'blackuot' : ''}>
        <div onClick={handleModalContentClick} className={styles.register + ' ' + (!modal ? styles.hidden : '')}>
          <button onClick={toggleModal} className={styles.close}>
            <img className={styles.close} src={closIcon} alt="" />
          </button>
          <div className={styles.register__title}>Register</div>
          <div className={styles['register__input-item']}>
            <input
              type="email"
              placeholder='Email address'
              name='email'
              value={values.email}
              autoComplete="off"
              onChange={handleChange}
              required
            />
          </div>
          <div className={styles['register__input-item']}>
            <input
              type="password"
              className={styles['password-input']}
              placeholder='Password'
              name='password'
              value={values.password}
              autoComplete="off"
              onChange={handleChange}
              required
            />
          </div>
          <div className={styles['register__input-item']}>
            <input
              type="text"
              placeholder='Username'
              name='name'
              value={values.name}
              autoComplete="off"
              onChange={handleChange}
              required
            />
          </div>
          <button type='submit' className={styles['Have-button']}>I already have an account</button>
          <button type='submit' className={styles['register-button']}>Create an account</button>
        </div>
      </div>
    </>
  );
}

export default Register;
